UPDATE pf.skill_import_outbox SET state='PUBLISHED',relay_owner=NULL,relay_until=NULL
  WHERE id=#{publication.id} AND space_id=#{publication.spaceId} AND import_id=#{publication.importId}
   AND generation=#{publication.generation} AND state='PUBLISHING' AND relay_owner=#{publication.relayOwner}

mapper.select:
SELECT  FROM pf.skill_import i JOIN pf.skill_import_outbox o
  ON o.import_id=i.id AND o.space_id=i.space_id AND o.generation=i.generation WHERE o.id=#{publication.id}
  AND o.space_id=#{publication.spaceId} AND o.import_id=#{publication.importId} AND o.generation=#{publication.generation} FOR UPDATE OF i

SELECT  FROM pf.skill_import i
  WHERE i.id=#{command.importId} AND i.space_id=#{command.spaceId} AND i.owner_user_id=#{command.actorId}
   AND i.owner_id=#{command.ownerId} AND i.generation=#{command.generation} AND i.fence=#{command.fence}
   AND i.staging_object_key=#{command.objectKey} AND i.declared_bytes=#{command.bytes} AND i.declared_sha256=#{command.sha256}
   AND i.state='RUNNING' AND i.lease_until>clock_timestamp() FOR UPDATE OF i

