UPDATE pf.skill_import SET state='DRAFT',capability_id=target_capability_id,version_id=target_version_id,
  owner_id=NULL,fence=NULL,lease_until=NULL,revision=revision+1 WHERE id=#{command.importId} AND space_id=#{command.spaceId}
  AND state='RUNNING' AND owner_id=#{command.ownerId} AND generation=#{command.generation} AND fence=#{command.fence} AND lease_until>clock_timestamp()
